import { cssModulesConfig } from "gatsby-1-config-css-modules"

exports.modifyWebpackConfig = ({ config, stage }, options = {}) => {
  const lessFiles = /\.less$/
  const lessModulesFiles = /\.module\.less$/

  let theme
  if (options.theme) {
    if (typeof options.theme === `object`) {
      theme = options.theme
    } else if (typeof options.theme === `string`) {
      theme = require(options.theme)
    }
  }
  const themeJson = theme ? JSON.stringify(theme) : null

  switch (stage) {
    case `develop`: {
      const lessLoader = themeJson
        ? `less?{"sourceMap":true,"modifyVars":${themeJson}}`
        : `less?{"sourceMap":true}`

      config.loader(`less`, {
        test: lessFiles,
        exclude: lessModulesFiles,
        loaders: [`style`, `css`, lessLoader],
      })

      config.loader(`lessModules`, {
        test: lessModulesFiles,
        loaders: [`style`, cssModulesConfig(stage), lessLoader],
      })
      return config
    }
    case `build-css`: {
      const lessLoader = themeJson ? `less?{"modifyVars":${themeJson}}` : `less`

      config.loader(`less`, {
        test: lessFiles,
        exclude: lessModulesFiles,
        loader: ExtractTextPlugin.extract([`css?minimize`, lessLoader]),
      })

      config.loader(`lessModules`, {
        test: lessModulesFiles,
        loader: ExtractTextPlugin.extract(`style`, [
          cssModulesConfig(stage),
          lessLoader,
        ]),
      })
      return config
    }
    case `develop-html`:
    case `build-html`:
    case `build-javascript`: {
      const lessLoader = themeJson ? `less?{"modifyVars":${themeJson}}` : `less`

      config.loader(`less`, {
        test: lessFiles,
        exclude: lessModulesFiles,
        loader: `null`,
      })

      config.loader(`lessModules`, {
        test: lessModulesFiles,
        loader: ExtractTextPlugin.extract(`style`, [
          cssModulesConfig(stage),
          lessLoader,
        ]),
      })
      return config
    }
    default: {
      return config
    }
  }
}
